const THEMES={midnight:{bg:'#080a0e',panel:'#10141a',header:'#14191f',border:'#27303a',row:'#1d242c',hover:'#242c35',text:'#e8edf4',dim:'#8e9aaa',accent:'#7188ff',input:'#151b22',selected:'#202a3f',warn:'#292511',error:'#2a181b',info:'#172333',success:'#15251d'},amoled:{bg:'#000',panel:'#050505',header:'#0b0b0b',border:'#202020',row:'#141414',hover:'#1c1c1c',text:'#f2f2f2',dim:'#8a8a8a',accent:'#9b8cff',input:'#0d0d0d',selected:'#211b3b',warn:'#242000',error:'#260c10',info:'#071521',success:'#071b12'},slate:{bg:'#11161c',panel:'#1a2129',header:'#202933',border:'#34404b',row:'#252e38',hover:'#303b47',text:'#e3e9ef',dim:'#9aa7b5',accent:'#86a6c9',input:'#232c35',selected:'#2b3b4b',warn:'#2e2b1b',error:'#321d22',info:'#1b2a38',success:'#1b2d25'},bluegrey:{bg:'#0d141b',panel:'#15202a',header:'#1b2935',border:'#304352',row:'#1e2d39',hover:'#283b49',text:'#e2ebf2',dim:'#91a4b4',accent:'#74a8d8',input:'#1b2a35',selected:'#20394e',warn:'#2c2b1c',error:'#2d1c23',info:'#172d40',success:'#152b25'},webinspector:{bg:'#000',panel:'#080808',header:'#111',border:'#303030',row:'#171717',hover:'#202020',text:'#dedede',dim:'#929292',accent:'#8ab4f8',input:'#0b0b0b',selected:'#173b68',warn:'#2a2300',error:'#321317',info:'#101f30',success:'#0e2518'}};
function loadStoredSettings(){try{const value=JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}'),version=Number(value.version)||0,next={...DEFAULT_SETTINGS,...value};if(value.version!==SETTINGS_VERSION&&value.theme==='midnight')next.theme=DEFAULT_SETTINGS.theme;if(version<4)next.experimentalPersistence=true;if(!THEMES[next.theme])next.theme=DEFAULT_SETTINGS.theme;next.version=SETTINGS_VERSION;next.syntax=next.syntax!==false;next.timestamps=next.timestamps!==false;next.autocomplete=next.autocomplete!==false;next.experimentalPersistence=true;next.networkCapture=next.networkCapture!==false;next.pageScripts=next.pageScripts!==false;next.virtualKeyHelpers=next.virtualKeyHelpers===true;return next}catch(e){return{...DEFAULT_SETTINGS}}}
