function applyTheme(name){const t=THEMES[name]||THEMES.midnight;settings.theme=THEMES[name]?name:'midnight';themeStyle.textContent=`#wrap{background:${t.bg};border-color:${t.border};color:${t.text}}#dragbar,#topbar,#console-input-wrap,.tool-row,.net-header,.storage-head,.editor-head,.editor-actions,.settings-head{background:${t.header};border-color:${t.border}}.btn,.mini,.tool-row select,.settings-line select{background:${t.panel};border-color:${t.border};color:${t.text}}.panel-search{background:${t.bg};border-color:${t.border};color:${t.text}}.execution-status{background:${t.error};border-color:#c95762;color:#f3a1a7}.tab{color:${t.dim}}.tab.active{color:${t.accent};border-bottom-color:${t.accent}}.log-entry,.net-row,.storage-kv,.style-row{border-color:${t.row}}.log-warn{color:#e3c469;background:${t.warn}}.log-error{color:#f08a91;background:${t.error}}.log-info{color:#8bc7ff;background:${t.info}}.log-success{color:#76d99b;background:${t.success}}#console-input{border-color:${t.border};color:${t.text};background:${t.input}}#console-input:focus{border-color:${t.accent};background:${t.input}}#code-editor.syntax-off #console-input{background:${t.input};color:${t.text}}#run-btn{background:${t.accent}}.node-line:hover,.net-row:hover{background:${t.hover}}.node-line.selected{background:${t.selected};outline-color:${t.accent}}.node-tag{color:#e58a92}.node-attr-name{color:#e0ae7d}.node-attr-val{color:#9ed18a}.node-text,.empty-msg,.tool-label,.storage-head,.style-section h4{color:${t.dim}}.sk{color:${t.accent}}.sv,.sv2{color:${t.text}}.sk2{color:${t.accent}}.editor-modal,.settings-drawer{background:${t.panel};border-color:${t.border}}.editor-textarea{background:${t.bg};color:${t.text}}#syntax-layer{color:${t.text}}#syntax-layer .tok-comment{color:${t.dim}}#syntax-layer .tok-string{color:#9ed18a}#syntax-layer .tok-number{color:#dfb979}#syntax-layer .tok-keyword{color:${t.accent}}#syntax-layer .tok-literal{color:#d99ad9}.log-time{color:${t.dim}}.source-row{border-color:${t.border}}.source-row:hover{background:${t.hover}}.metric-grid{background:${t.border};border-color:${t.border}}.metric-card{background:${t.panel}}.metric-label{color:${t.dim}}.metric-value{color:${t.text}}.waterfall-track{background:${t.bg}}.waterfall-track i{background:${t.accent}}.user-script-info,.user-script-note{background:${t.panel};border-color:${t.border};color:${t.dim}}.user-script-info strong{color:${t.text}}.user-script-state{color:#76d99b}.user-script-warning{color:#e3c469}`;if(settings.theme==='webinspector')themeStyle.textContent+=`#wrap{border-radius:0;box-shadow:none}#dragbar{height:14px}#topbar{height:34px;padding:0 4px}.tab-icon{display:none}.tab{height:34px;padding:0 9px;font-size:11px;gap:4px}.tab-icon{font-size:11px}.btn,.mini{min-height:24px;padding:3px 7px;border-radius:2px;font-size:10px}.mini{padding:3px 6px}#content{font-size:12px}.log-entry{padding:4px 8px;font-size:11px;gap:6px}.net-row{padding:5px 8px;font-size:10px}.tool-row{padding:5px 8px;gap:4px}#console-input-wrap{padding:5px 8px;gap:5px}#console-prompt{font-size:12px}#run-btn{min-height:28px;padding:5px 10px;border-radius:2px;font-size:11px}.node-line{padding:3px 6px;margin:0 2px;border-radius:0}.node-children{padding-left:14px}.storage-head{padding:6px 8px}.storage-kv{padding:4px 8px}.editor-modal,.settings-drawer{border-radius:2px;box-shadow:none}.editor-head,.settings-head{padding:7px 8px}.editor-actions{padding:5px 8px}.network-detail,.inspection-report{margin:7px 8px;border-radius:2px;padding:8px}`}
function syntaxHighlight(source){const tokenRe=/(\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b\d+(?:\.\d+)?\b|\b(?:const|let|var|function|return|if|else|for|while|new|class|extends|try|catch|throw|async|await|typeof|instanceof|in|of|switch|case|break|continue|import|from|export)\b|\b(?:true|false|null|undefined|NaN)\b)/g;let html='',last=0;String(source).replace(tokenRe,(token,_match,offset)=>{html+=esc(source.slice(last,offset));let kind='number';if(/^\/\//.test(token)||/^\/\*/.test(token))kind='comment';else if(/^["'`]/.test(token))kind='string';else if(/^(true|false|null|undefined|NaN)$/.test(token))kind='literal';else if(/^[A-Za-z]/.test(token))kind='keyword';html+=`<span class="tok-${kind}">${esc(token)}</span>`;last=offset+token.length;return token});return html+esc(String(source).slice(last))}
function renderSyntax(){const input=$('#console-input'),layer=$('#syntax-layer');if(!input||!layer)return;if(settings.syntax){layer.innerHTML=syntaxHighlight(input.value)||' ';layer.scrollTop=input.scrollTop;layer.scrollLeft=input.scrollLeft}else layer.textContent=''}
function hideCompletions(){const panel=$('#completion-panel');if(panel){panel.hidden=true;panel.innerHTML=''}}
function showCompletions(force=false){const input=$('#console-input'),panel=$('#completion-panel');if(!input||!panel)return;const before=input.value.slice(0,input.selectionStart),member=before.match(/([A-Za-z_$][\w$]*)\.([A-Za-z_$][\w$]*)?$/),prefix=member?member[2]||'':(before.match(/[A-Za-z_$][\w$]*$/)||[''])[0];if(!force&&((!member&&prefix.length<2)||(member&&!prefix))){hideCompletions();return}let target=window;if(member){const base=member[1];try{target=base==='document'?document:base==='console'?console:base==='window'?window:window[base]||{}}catch(e){target={}}}let names=[];try{names=Object.getOwnPropertyNames(target)}catch(e){}if(!member)names=[...new Set([...names,'document','window','console','location','localStorage','sessionStorage','fetch','setTimeout','setInterval','JSON','Math','Array','Object','String','Number','Date'])];const lower=prefix.toLowerCase(),matches=names.filter(name=>name.toLowerCase().startsWith(lower)&&name!==prefix).sort((a,b)=>a.localeCompare(b)).slice(0,24);if(!matches.length){hideCompletions();return}panel.innerHTML=matches.map(name=>`<button class="completion-item" data-completion="${esc(name)}">${esc(name)}</button>`).join('');panel.hidden=false}
function applyCompletion(value){const input=$('#console-input');if(!input)return;const before=input.value.slice(0,input.selectionStart),after=input.value.slice(input.selectionEnd),match=before.match(/[A-Za-z_$][\w$]*$/),start=match?input.selectionStart-match[0].length:input.selectionStart;input.value=before.slice(0,start)+value+after;input.selectionStart=input.selectionEnd=start+value.length;renderSyntax();hideCompletions();input.focus()}
